paper = open('/home/user/gp-rarelink/data/literature/ssadh/fulltext_md/19484191.md', encoding='utf-8').read()
data = json.load(open('/home/user/gp-rarelink/data/extracted/ssadh/ow-ssadh/per_paper/19484191.json', encoding='utf-8'))
schema = json.load(open('/home/user/gp-rarelink/pipeline/extract/claude_code/schema_ssadh_v5.json', encoding='utf-8'))
fields = {t['name']: [f['name'] for f in t['fields']] for t in schema['tables']}

bad = []
n = 0
for tname, rows in data['tables'].items():
    for i, r in enumerate(rows):
        if set(r) != set(fields[tname]):
            bad.append(('FIELDS', tname, i, set(fields[tname]) ^ set(r)))
        for f, cell in r.items():
            spans = cell.get('span')
            if spans is None: continue
            if isinstance(spans, str): spans = [spans]
            for s in spans:
                n += 1
                if s not in paper: bad.append(('SPAN', tname, i, f, s))
print('spans checked:', n)
print('rows:', {k: len(v) for k, v in data['tables'].items()})
print('bad:', bad)
